import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xid11')
from h import *
L=[]
L.append(T(3151182,"Scone Gurih Cheddar dan Sage","Dengan protein lebih tinggi daripada beberapa camilan lain, scone ini bisa menjadi suguhan yang menyenangkan saat menjalani dialisis.","8",None,
["350 g tepung terigu biasa","1 sendok teh cream of tartar","½ sendok teh soda kue","50 g mentega tawar","100 g cheddar, diparut","1 sendok teh sage kering","1 telur, dikocok","250 ml susu kedelai organik"],
["Panaskan oven hingga 190°C/ 170°C fan/ gas mark 5. Alasi loyang. Dalam mangkuk, campurkan tepung, cream of tartar, dan soda kue, lalu gosok-gosokkan mentega hingga menyerupai remah roti halus.","Campurkan 80 g keju cheddar parut dan sage kering. Buat cekungan di tengah dan tuang susu. Dengan pisau yang digerakkan seperti memotong, campur menjadi adonan.","Taburi permukaan kerja dan tangan Anda dengan tepung, keluarkan adonan dan uleni sampai halus, lalu bentuk bulat setebal sekitar 3 cm. Letakkan di atas loyang dan beri tanda menjadi 8 irisan. Olesi dengan telur kocok dan taburi dengan sisa 20 g cheddar.","Panggang selama 20 menit sampai keemasan. Paling enak disajikan hangat dengan sedikit mentega."],
[g("chef","Alternatif gurih yang lezat pengganti roti gulung untuk disantap dengan sup, atau nikmati sebagai bekal makan siang."),g("carb","Sumber utama karbohidrat adalah tepung dalam scone ini, nilai karbohidrat telah dicantumkan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Cream of tartar merupakan sumber kalium tetapi lebih rendah fosfat daripada baking powder. Takaran yang digunakan memungkinkan resep ini dijadikan camilan sesekali pada diet rendah kalium.\nSusu kedelai organik lebih rendah fosfat dan kalium daripada susu sapi sehingga digunakan di sini untuk mengurangi kandungan fosfat dan kalium.\nKeju dan kue panggang sering kali tinggi fosfat, jadi harap minum pengikat fosfat bersama camilan ini jika Anda diresepkan obat tersebut."),g("prot","Bahan scone (susu, telur, dan cheddar) membuatnya tidak cocok bagi mereka yang menjalani diet rendah protein."),g("gf","Gunakan tepung bebas gluten."),g("health","Gunakan tepung gandum utuh dan keju rendah lemak."),g("store","Dapat bertahan dalam wadah kedap udara di lemari es selama tiga hari.")],
[]))
L.append(T(3154406,"Bungkusan Labu Butternut dan Keju Kambing","Merebus sayuran dalam hidangan ini membantu menurunkan kalium, tetapi dengan tambahan keju kambing, rasanya tetap kaya.","4",None,
["1 lembar puff pastry siap gulung","1 labu butternut, dikupas dan dipotong dadu","1 ubi jalar besar, dikupas dan dipotong dadu","1 bawang bombai kecil, dicincang","5 g biji wijen atau biji bawang","1 sendok teh minyak zaitun","60 g keju kambing lunak","1 telur, dikocok","Sejumput lada hitam bubuk",("Untuk penyajian","240 g selada, diiris"),("Untuk penyajian","80 g mentimun, diiris")],
["Panaskan oven terlebih dahulu hingga 180°c/ 160°c fan/ gas mark 4. Masukkan ubi jalar dan labu butternut ke dalam panci, tutupi dengan air dan didihkan, masak sampai lunak.","Tiriskan ubi jalar dan labu butternut lalu tuang ke dalam loyang pemanggang bersama bawang bombai cincang. Siram dengan minyak zaitun, taburi dengan lada hitam, dan panggang selama 20 menit. Angkat dari oven dan biarkan dingin.","Potong pastry menjadi 8 persegi panjang yang sama besar. Letakkan 4 persegi panjang di atas loyang beralas dan sendokkan ¼ campuran sayuran ke tengah setiap persegi panjang, sisakan celah di sekeliling tepi. Taburkan 15 g keju kambing yang dihancurkan di atas setiap campuran sayuran. Olesi sedikit telur kocok pada tepi pastry di sekelilingnya.","Ambil 4 persegi panjang yang tersisa, lipat longgar menjadi dua memanjang dan buat 5 sayatan menembus kedua lapisan, sisakan tepi. Buka lipatannya dan letakkan di atas 4 bungkusan, tekan tepinya ke tepi lapisan bawah yang sudah diolesi telur untuk merekatkan bungkusan Anda.","Olesi bagian atas dengan olesan telur dan taburi dengan biji wijen atau biji bawang lalu panggang selama 25 menit sampai keemasan. Setelah matang, angkat dari oven.","Setelah matang, angkat dari oven, dan sajikan dengan salad hijau."],
[g("chef","Hidangan lezat yang cepat dan mudah disiapkan."),g("carb","Sumber utama karbohidrat dalam hidangan ini adalah ubi jalar, labu butternut, dan pastry. Nilai karbohidrat diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Kami merebus labu butternut dan ubi jalar alih-alih memanggangnya untuk mengurangi kandungan kalium.\nHanya ada sedikit keju lunak dalam hidangan ini yang menyumbang fosfat sehingga kandungan fosfat secara keseluruhan rendah."),g("prot","Hidangan ini rendah protein; Anda dapat mempertimbangkan untuk menggandakan keju guna menambah protein sambil tetap mempertahankan hidangan rendah kalium dan fosfat."),g("gf","Gunakan pastry bebas gluten."),g("vegan","Gunakan keju vegan."),g("health","Pastry tinggi lemak; untuk pilihan yang lebih sehat Anda dapat menghilangkan lapisan pastry atas dan membuat bungkusan terbuka."),g("tips","Labu butternut dan ubi jalar tersedia dalam bentuk yang sudah disiapkan di bagian beku sebagian besar supermarket jika Anda kesulitan mengupasnya di rumah.")],
[]))
L.append(T(3162079,"Wrap Ayam Caesar","Wrap tinggi protein yang lezat, ramah ginjal dan cocok untuk bekal. Wrap ini juga rendah kalium dan fosfat, sehingga ideal untuk dibawa saat dialisis.","4",None,
["175 g ayam matang","50 g mayones","1 siung bawang putih, dimemarkan","50 g keju Parmesan satu potong","100 g selada iceberg, dicincang kasar","¼ sendok teh saus Worcestershire","Lada hitam","4 tortilla lembut"],
["Suwir ayam matang menjadi serat memanjang dan masukkan ke dalam mangkuk bersama daun selada cincang dan bawang putih yang dimemarkan.","Serut Parmesan menjadi irisan tipis ke dalam mangkuk, lalu tambahkan mayones dan saus Worcestershire dan aduk perlahan hingga tercampur, bumbui dengan lada.","Untuk merakit wrap, sendokkan ¼ campuran ke bagian bawah tortilla. Lipat bagian bawah tortilla ke atas dan menutupi isian.","Lipat dua kali di kedua sisi dan gulung dengan kencang. Ulangi dengan tiga tortilla yang tersisa. Santap utuh atau potong menjadi dua untuk segera disajikan, atau bungkus dengan aluminium foil agar tetap utuh sampai Anda ingin memakannya."],
[g("chef","Salad Caesar klasik telah diolah kembali menjadi wrap, yang sempurna untuk makan siang cepat atau makan malam ringan."),g("carb","Sumber utama karbohidrat dalam hidangan ini berasal dari tortilla wrap. Nilai karbohidrat hidangan ini diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Jika Anda mengikuti ukuran penyajian yang diberikan dalam resep ini, hidangan ini rendah kalium dan fosfat. Ayam dan keju Parmesan sama-sama mengandung fosfat, tetapi porsi kecil yang digunakan dalam resep ini menjaga kandungan fosfat secara keseluruhan tetap rendah. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Ayam dan keju yang digunakan dalam resep ini menyediakan sumber protein yang sangat baik bagi orang yang menjalani dialisis dan siapa pun yang perlu makan lebih banyak protein."),g("gf","Gunakan tortilla wrap bebas gluten."),g("veg","Gunakan potongan bebas daging bergaya ayam atau kacang arab sebagai gantinya. Periksa apakah keju Parmesan Anda cocok untuk vegetarian."),g("vegan","Gunakan potongan bebas daging bergaya ayam atau kacang arab sebagai gantinya. Gunakan mayones bebas susu yang sesuai dan keju keras bergaya Italia bebas susu."),g("health","Tidak ada garam yang ditambahkan dalam resep ini. Keju Parmesan, saus Worcestershire, mayones, dan tortilla wrap mengandung garam, yang membuat resep ini sedikit di atas kisaran untuk digolongkan sebagai hidangan rendah garam. Untuk meminimalkan kandungan garam, pilih wrap dengan kandungan garam terendah. Takar saus Worcestershire, mayones, dan keju Parmesan agar tidak menambahkan terlalu banyak. Untuk menurunkan kandungan garam lebih jauh, Anda dapat mempertimbangkan menggunakan satu sendok teh air perasan lemon sebagai pengganti saus Worcestershire dan sedikit yoghurt alami sebagai pengganti mayones.\nJika Anda ingin menurunkan lemak dalam hidangan ini, pilih mayones rendah lemak.\nMenggunakan wrap gandum utuh akan menambah serat dalam makanan Anda."),g("store","Setelah dibuat, simpan di lemari es dan gunakan dalam dua hari. Saat dikemas untuk makan siang, kami menyarankan menggunakan cool pack agar tetap dingin."),g("tips","Jika Anda tidak membutuhkan empat porsi, Anda dapat mengurangi takaran resep.")],
[]))
L.append(T(3194515,"Salad Kacang dan Couscous","Hidangan rendah protein yang mudah disiapkan. Cocok untuk makan siang dan rendah kalium, fosfat, dan garam.","2",None,
["1 sendok makan minyak zaitun","1 bawang merah, dicincang halus","150 g couscous","240 ml kaldu sayuran rendah garam","1 paprika merah, dipotong 1 cm","400 g salad tiga kacang kalengan, dalam air","10 g peterseli segar, dicincang (opsional)"],
["Cincang bawang dan paprika lalu sisihkan.","Buat kaldu sayuran dan takar couscous. Aduk kaldu sayuran panas ke dalam couscous, tutup dan diamkan selama lima menit.","Panaskan minyak zaitun dalam panci kecil. Tumis bawang dengan api kecil selama lima menit atau sampai lunak, lalu angkat panci dari api.","Buka tutup couscous dan gunakan garpu untuk menggemburkannya. Tambahkan bawang yang sudah dimasak dan paprika segar, lalu tiriskan salad kacang dan tambahkan ke couscous. Aduk perlahan sampai tercampur rata. Jika menggunakan peterseli, taburkan di atas salad sebelum disajikan."],
[g("chef","Salad kacang dan couscous vegan yang mudah dan dapat disiapkan lebih dulu untuk makan siang yang sehat."),g("carb","Sumber utama karbohidrat dalam hidangan ini berasal dari couscous dan kacang. Nilai karbohidrat hidangan ini diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Kacang memang mengandung kalium dan fosfat, tetapi dengan takaran dalam resep ini, kadar keseluruhannya rendah. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Resep ini rendah protein, yang baik bagi orang yang dianjurkan mengurangi protein. Jika Anda dianjurkan menambah protein, Anda mungkin ingin menambahkan satu kaleng kecil tuna. Carilah tuna dalam air mata air dan tiriskan sebelum digunakan."),g("gf","Gunakan soba atau quinoa dan kaldu sayuran bebas gluten sebagai pilihan bebas gluten."),g("store","Hidangan ini tahan lama dan dapat disimpan di lemari es hingga 3 hari.")],
[]))
L.append(T(3204614,"Udang Lada Karibia dengan Nasi Kelapa",">","4",None,
["450 g udang (mentah atau matang)","Gilingan lada hitam","1 sendok makan tepung maizena","2 cabai merah pedas, dipotong dadu halus","1 ikat daun bawang (bagian putih dan hijau), dipotong dadu halus","1 sendok makan minyak sayur","3 siung bawang putih, dicincang halus","240 g beras butir panjang, dibilas","400 ml santan kalengan","1 sendok makan minyak kelapa","30 g ketumbar segar, dicincang kasar",("Salad pendamping untuk disajikan","80 g selada, disobek kasar"),("Salad pendamping untuk disajikan","50 g mentimun, diiris"),("Salad pendamping untuk disajikan","2 tomat, diiris"),("Salad pendamping untuk disajikan","1 paprika, diiris"),("Salad pendamping untuk disajikan","Dressing salad rendah garam")],
["Siapkan nasi dengan memasukkan santan dan minyak kelapa ke dalam panci lalu didihkan. Masukkan beras, didihkan kembali, lalu kecilkan api dan tutup panci. Masak nasi sampai semua cairan terserap. Angkat dari api dan diamkan beberapa menit.","Selagi nasi dimasak, campurkan udang dengan tepung maizena, lada hitam, paprika bubuk, dan serpihan cabai. Panaskan setengah minyak dalam wajan dengan api sedang lalu goreng udang – hanya sebentar untuk memanaskan kembali jika menggunakan udang matang; lebih lama jika menggunakan udang mentah, agar benar-benar matang.","Dalam panci terpisah, panaskan sisa minyak dengan api sedang/kecil dan masak cabai, daun bawang (bagian putih saja), dan bawang putih selama sekitar 3 menit. Masukkan udang matang, bersama bagian hijau daun bawang dan aduk semuanya. Udang sudah dimasak sehingga ini hanya diaduk sebentar.","Siapkan salad pendamping dengan mencampur selada, mentimun, tomat, dan paprika lalu bumbui dengan dressing salad favorit Anda.","Sajikan udang di atas nasi kelapa, dengan taburan ketumbar segar dan salad di sampingnya."],
[g("chef","Hidangan udang yang cepat dan mudah, rendah fosfat, kalium, dan garam."),g("carb","Nasi adalah sumber utama karbohidrat, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("pk","Resep ini rendah kalium, jika mengikuti takaran dan ukuran penyajian yang diberikan, sehingga cocok jika Anda dianjurkan mengurangi jumlah kalium dalam diet Anda. Resep ini juga rendah fosfat, tetapi tetap mengandung sedikit, terutama dari udang, jadi jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini menyediakan sumber protein. Jika Anda dianjurkan makan lebih banyak protein, pertimbangkan untuk mendapatkan protein tambahan pada hidangan lain di sepanjang hari."),g("safety","Jika Anda menggunakan udang mentah, pastikan udang dimasak hingga matang sepenuhnya untuk menghindari risiko infeksi."),g("serve","Hidangan ini paling enak dimakan saat baru dibuat."),g("health","Jika Anda ingin membuat hidangan ini lebih rendah lemak, pertimbangkan untuk menggunakan santan ringan/rendah lemak.")],
[]))
L.append(T(3227420,"Salad Ayam Lengket Asia",">","2",None,
["150 g daging dada ayam mentah","1 siung bawang putih, dimemarkan","1 sendok makan kecap asin rendah garam","1 sendok makan madu atau sirup maple","150 g kubis putih, diiris sangat tipis","1 sendok makan minyak wijen","2 wortel, dikupas dan diiris sangat tipis","3 daun bawang, diiris tipis memanjang","¼ mentimun, dipotong batang halus","Segenggam kecil daun mint","40 g almond atau kacang tanah polos tanpa garam yang dicincang, dicincang kasar","1 sendok makan biji wijen, disangrai","100 g mi beras kering"],
["Letakkan dada ayam di antara plastik wrap dan pukul dengan rolling pin sampai pipih. Iris ayam menjadi potongan memanjang.","Campurkan kecap asin, madu, bawang putih, dan setengah minyak wijen dalam mangkuk dan kocok sampai tercampur. Masukkan ayam ke dalam marinade, aduk rata, tutup dan dinginkan setidaknya selama 20 menit.","Panaskan sisa minyak wijen dalam wajan dengan api sedang/besar, lalu masukkan potongan ayam dan goreng sampai matang sepenuhnya. Angkat ayam dari wajan dan sisihkan di atas piring.","Kecilkan api dan masukkan sisa campuran marinade lalu masak sampai terbentuk dressing yang lengket, sekitar 5 menit. Biarkan dingin.","Didihkan seteko penuh air dan tuang air mendidih ke dalam mangkuk. Masukkan mi ke dalam air dan diamkan selama 3 menit. Tiriskan.","Masukkan bahan yang tersisa ke dalam mangkuk dan campurkan ayam dan mi dengan perlahan. Sajikan dengan dressing yang disiramkan di atasnya."],
[g("chef","Salad dengan cita rasa kaya yang terinspirasi Asia, rendah garam, kalium, dan fosfat."),g("carb","Mi beras adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, jika mengikuti takaran dalam daftar bahan dan ukuran penyajian. Karena itu cocok bagi mereka yang dianjurkan mengurangi kalium dalam diet mereka. Resep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat (terutama dari ayam dan kacang) jadi jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini menyediakan sumber protein. Untuk pilihan yang lebih rendah protein, pertimbangkan untuk mengurangi ayam menjadi 75 g dan menambahkan satu kaleng kecil (200 g) kacang arab yang ditiriskan pada langkah 6."),g("tips","Minyak wijen lebih mahal, tetapi sepadan dengan biaya tambahan, karena sedikit saja memberikan rasa yang luar biasa. Kecap asin rendah garam tetap mengandung garam, jadi takar dengan cermat.")],
[]))
L.append(T(3236439,"Tart Filo Ceri","Puding yang sempurna, cocok untuk semua orang.","6",None,
["250 g ceri beku tanpa biji","75 g gula pasir","1 sendok teh esens vanila","1 sendok makan tepung arrowroot","1 sendok makan air","1 kotak filo pastry siap pakai (sekitar 250 g)","1 sendok makan minyak","60 g mentega","1 sendok makan gula halus"],
["Masukkan ceri beku, gula, dan esens vanila ke dalam panci. Masak dengan api sedang selama 5 menit, sering diaduk. Hancurkan ceri perlahan dengan spatula. Campurkan tepung arrowroot dan air hingga membentuk pasta.","Tambahkan pasta ke ceri yang sudah dimasak, sambil diaduk saat menuangkannya. Didihkan, lalu angkat dari api dan biarkan dingin. Panaskan oven terlebih dahulu hingga 190°C / 170°C fan / gas mark 5 dan olesi loyang muffin dengan lemak.","Ambil tiga lembar pastry dan potong masing-masing menjadi empat persegi. Lelehkan mentega dan olesi pastry di kedua sisi lalu alasi enam lubang dengan dua persegi di masing-masing. Tambahkan satu sendok makan isian ceri ke masing-masing. Lipat tepi filo pastry di atas isian ceri untuk menutup secara longgar.","Olesi setiap tart dengan mentega tambahan. Panggang dalam oven selama 10-15 menit, sampai pastry berwarna cokelat keemasan muda di seluruh permukaan. Angkat dari oven dan pindahkan ke rak pendingin. Setelah dingin, taburi dengan gula bubuk. Sajikan hangat atau pada suhu ruang."],
[g("chef","Menggunakan ceri beku dan pastry siap pakai berarti tart ini dapat dibuat untuk acara istimewa sepanjang tahun."),g("carb","Sumber utama karbohidrat dalam hidangan ini adalah ceri, gula, dan filo pastry. Nilai karbohidrat diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini mengandung ceri yang tinggi kalium, tetapi jika digunakan sesuai takaran yang ditentukan dalam resep, hidangan ini tetap rendah kalium.\nHidangan ini mengandung sedikit fosfat yang terutama berasal dari filo pastry. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Hidangan ini rendah protein dan menjadi puding yang cocok untuk acara istimewa jika Anda dianjurkan menjalani diet rendah protein."),g("gf","Terkadang sulit menemukan filo pastry siap pakai yang bebas gluten, sehingga Anda mungkin ingin menggunakan puff pastry bebas gluten sebagai gantinya."),g("vegan","Banyak filo pastry siap pakai bebas susu. Gunakan olesan bebas susu sebagai pengganti mentega."),g("health","Jika Anda ingin mengurangi jumlah gula atau lemak yang Anda makan, kurangi takaran gula yang digunakan dalam isian ceri, atau ganti dengan pemanis. Pertimbangkan menggunakan olesan rendah lemak sebagai pengganti mentega."),g("cheap","Ekstrak vanila dapat digunakan sebagai pengganti polong vanila."),g("store","Setelah dingin, simpan dalam wadah kedap udara di lemari es dan makan dalam dua hari.")],
[]))
save(4,L)
